import { Router } from "express";
import { query } from "../db.js";

export const webhooks = Router();

webhooks.post("/carrier", async (req, res) => {
  const { trackingNumber, status, occurredAt } = req.body ?? {};
  const at = new Date(occurredAt);
  if (!trackingNumber || !status || Number.isNaN(at.getTime())) {
    res.status(400).json({ error: "trackingNumber, status and a valid occurredAt are required" });
    return;
  }

  // Single conditional UPDATE so the staleness check and the write are atomic;
  // events older than the stored status_at are ignored.
  const updated = await query<{ id: string }>(
    `UPDATE parcels SET status = $2, status_at = $3
     WHERE tracking_number = $1 AND (status_at IS NULL OR status_at <= $3)
     RETURNING id`,
    [String(trackingNumber).toUpperCase(), String(status), at],
  );

  // Always 200 so the carrier doesn't retry stale or unknown events.
  res.status(200).json({ applied: updated.length > 0 });
});

